void SS_ig_pc_init_function(	PC_ref 	*SS_pc_xeos,
							    int 	 iss,
							    char 	*name,
							    global_variable gv			){

	if      (strcmp( name, "bi")  == 0 ){
		SS_pc_xeos[iss].ss_pc_xeos  = ig_bi_pc_xeos; 		}
	else if (strcmp( name, "fper")  == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = ig_fper_pc_xeos;      }
	else if (strcmp( name, "cd")  == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = ig_cd_pc_xeos; 		}
	else if (strcmp( name, "cpx") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = ig_cpx_pc_xeos; 		}
	else if (strcmp( name, "ep")  == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = ig_ep_pc_xeos; 		}
	else if (strcmp( name, "fl")  == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = ig_fl_pc_xeos; 		}
	else if (strcmp( name, "g")   == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = ig_g_pc_xeos; 		}
	else if (strcmp( name, "amp")  == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = ig_amp_pc_xeos; 		}
	else if (strcmp( name, "ilm") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = ig_ilm_pc_xeos; 		}
	else if (strcmp( name, "liq") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = ig_liq_pc_xeos; 		}
	else if (strcmp( name, "liqmn") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igmn_liq_pc_xeos; 		}
	else if (strcmp( name, "mu")  == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = ig_mu_pc_xeos; 		}
	else if (strcmp( name, "ol")  == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = ig_ol_pc_xeos; 		}
	else if (strcmp( name, "opx") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = ig_opx_pc_xeos; 		}
	else if (strcmp( name, "fsp") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = ig_fsp_pc_xeos; 	    }
	else if (strcmp( name, "spl") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = ig_spl_pc_xeos; 		}
	else if (strcmp( name, "chl") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = ig_chl_pc_xeos; 		}
	else if (strcmp( name, "DEW") == 0){

		struct ss_pc *DEW_pc_xeos = calloc(1, sizeof(struct ss_pc));
		SS_pc_xeos[iss].pc_own = DEW_pc_xeos;

		int id[gv.len_ox];
		DEW_build_id_map(gv.len_ox, gv.ox, id);

		int n_active = 0;
		int n_survive = 0;
		for (int s = 0; s < gv.n_dew_db; s++){
			DEW_db sp = Access_DEW_DB(s);
			if (!DEW_species_active(sp, gv.len_ox, id)){ continue; }
			int touches_other_zero = 0;
			for (int j = 0; j < gv.len_ox; j++){
				if (j == gv.O_id){ continue; }
				if (gv.bulk_rock[j] == 0. && sp.Comp[id[j]] != 0.){ touches_other_zero = 1; break; }
			}
			int mu_depends_on_O = (gv.O_id >= 0 && sp.MuComp[id[gv.O_id]] != 0.);
			int suppressed = (touches_other_zero || mu_depends_on_O) ? 1 : 0;
			DEW_pc_xeos[0].xeos_pc[n_active] = suppressed ? 0.0 : 1e-6;
			if (!suppressed){ n_survive++; }
			n_active++;
		}
		DEW_pc_xeos[0].xeos_pc[n_active] = 1.0 - n_survive*1e-6;

		SS_pc_xeos[iss].ss_pc_xeos  = DEW_pc_xeos; 		}
	else{
		printf("\nsolid solution '%s' is not in the database, cannot be initiated\n", name);
	}
}
